const q = $input.first().json.query || {};
const ok = q['hub.mode'] === 'subscribe' && q['hub.verify_token'] === $env.WEBHOOK_VERIFY_TOKEN;
return [{ json: { body: ok ? q['hub.challenge'] : 'token invalido', statusCode: ok ? 200 : 403 } }];

const out = [];
for (const item of $input.all()) {
  const body = item.json.body || item.json;
  for (const e of (body.entry || [])) {
    for (const ch of (e.changes || [])) {
      const v = ch.value || {};
      const contacto = (v.contacts && v.contacts[0]) || {};
      for (const m of (v.messages || [])) {
        let texto = '';
        let inter_id = '';
        let imagen_id = '';
        if (m.type === 'text') texto = (m.text && m.text.body) || '';
        else if (m.type === 'image') imagen_id = (m.image && m.image.id) || '';
        else if (m.type === 'interactive') {
          const it = m.interactive || {};
          if (it.type === 'list_reply') inter_id = (it.list_reply && it.list_reply.id) || '';
          else if (it.type === 'button_reply') inter_id = (it.button_reply && it.button_reply.id) || '';
        }
        // Atribucion de pauta (v5): los webhooks de anuncios click-to-WhatsApp
        // traen m.referral con el source_id del anuncio. Solo llega en el
        // PRIMER mensaje; el Cerebro lo conserva en la sesion hasta el pedido.
        let fuente = '';
        if (m.referral) {
          const r = m.referral;
          fuente = 'ctwa:' + (r.source_id || r.ctwa_clid || r.source_url || 'anuncio');
        }
        out.push({ json: {
          wa_id: m.from,
          nombre: (contacto.profile && contacto.profile.name) || '',
          tipo: m.type,
          texto,
          inter_id,
          imagen_id,
          fuente,
          message_id: m.id
        }});
      }
    }
  }
}
return out;

// ============ TEXTOS DEL BOT (tono de venta) — EDITAR AQUÍ ============
// TODO el texto que ve el cliente (y los avisos al dueño) vive en este archivo.
// Para cambiar el tono o adaptar el bot a OTRO negocio: editar SOLO este
// archivo y regenerar el workflow con:
