// Reemplaza {placeholders} por sus valores: T(TEXTOS.eligeReferencia, { ref: '05', precio: '$250.000' })
function T(plantilla, vars) {
  return String(plantilla).replace(/\{(\w+)\}/g, (m, k) => (vars && k in vars) ? String(vars[k]) : m);
